+fn a_repeated_equal_state_word_keeps_one_section() {
+    let nc = "G21 G90\nS1000 M3\nG0 X1.\nS1000 M3\nG1 X2. F100 S1000\n";
+    let p = parse_in_time(nc, &ParseOptions::default()).expect("same state");
+    assert_eq!(p.sections.len(), 1);
